import json
p='country_unique.json'
raw=open(p,encoding='utf8',newline='').read()
d=json.loads(raw)
d['tobacco']['morocco']={"h":"What the Moroccan Customs and Indirect Taxes Administration says about tobacco","p":["The Administration des Douanes et Impôts Indirects (ADII) traveller guide for people arriving in Morocco (douane.gov.ma, read from an archived copy on 24 November 2026) says visitors may import, free of duties and taxes and without declaration or customs formalities, 200 grams of manufactured tobacco. It counts weight, not a number of cigarettes, and gives no age limit.","On the same list the guide allows one bottle of perfume (150 ml) and one of eau de toilette (250 ml), one 1-litre bottle of wine and one 1-litre bottle of spirits, and non-commercial objects up to a total value of 2,000 dirhams. Anything beyond these tolerances is subject to duties and taxes, and a receipt is given when you pay. The guide adds that personal medicines are admitted duty-free without prior ministry permission, with a signed undertaking and a prescription or medical certificate, and that plant products need a phytosanitary certificate. It does not mention e-cigarettes."],"src":"Source read: ADII, guide for travellers arriving in Morocco (douane.gov.ma, PDF), read from an archived copy on 24 November 2026. The guide is undated.","link":["https://www.douane.gov.ma/dms_prod/loadDocument?documentId=76361","ADII (Moroccan customs): guide for travellers arriving in Morocco"]}
open(p,'w',encoding='utf8',newline='').write(json.dumps(d,ensure_ascii=False,separators=(',',':'))+('\n' if raw.endswith('\n') else ''))
